mapper.select:
SELECT c.id, c.complaint_no, c.type, c.title, c.content, c.contact_phone, c.status, c.reply_content, c.reply_time, c.create_time, c.update_time, o.owner_name, o.owner_phone, h.house_number FROM complaint_suggestion c LEFT JOIN owner_info o ON c.owner_id = o.id AND o.is_deleted = 0 LEFT JOIN house_info h ON c.house_id = h.id AND h.is_deleted = 0 LEFT JOIN building_info b ON h.building_id = b.id AND b.is_deleted = 0 WHERE c.is_deleted = 0
AND b.community_id = #{communityId}
AND c.complaint_no LIKE CONCAT('%', #{complaintNo}, '%')
AND c.status = #{status}
AND c.type = #{type}
AND c.owner_id = #{ownerId}
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
ORDER BY c.create_time DESC
